import './App.css';
import CodeBox from './components/code-box';
import QuestionBubble from './components/question-bubble';
import ContentFetcher from './retrieve-question';

function App() {
  return (
    <div className="App">
      <div className='logo-line'>
        <img src="logo.jpg" alt="Logo" className="logo-image" />
      </div>
      <div className='content-wrapper'>
        <div className='content-line'>
          <div className='content-column'>
          <div class="form-group">
            <label className='problem-label' for="problem-number">
              Problem number:
              <input type="number" id="problem-number" name="problem-number" className='problem-input' />
              <button className='button'> Retrieve problem from Project Euler </button>
            </label>
          </div>
          <ContentFetcher
            baseUrl="https://projecteuler.net/problem=" // Replace with a real example URL
            divId="question-text" // Replace with the actual div ID
            lastNumberRange={[1, 3]} // Fetch questions 1 to 3
            renderContent={(fetchedContent) => {
            return fetchedContent.map((item, index) => (
              <QuestionBubble key={index} text={item.content} />
            ));
           }}
          />
          </div>
          <div className='content-column'>
            <CodeBox/>
            <button className='button'> Retrieve code and solution</button>
          </div>
        </div>
      </div>
      <div className='name-line'>
        <p className='name'>Created by Lucas Marques Felix</p>
      </div>
    </div>
  );
}

export default App;
